def render_doctrine_anchor(cat_id: str) -> str:
    """doctrine anchor (concern authority) を上流指針として章へ描画する (goal-spec C15)。

    正本 = doctrine-anchor-registry.json の category_concern_map / concerns。
    具体技術は直書きせず、concern ごとの authority と導く上流原則のみを示す。
    category_concern_map に未帰属でも、approved な pending 例外が concerns を解決していれば
    その concern の authority を上流指針として描画する (プロジェクト固有の確定を全プロジェクト
    共通シードへ昇格させずに反映する経路)。未解決の未帰属は pending 注記に留める (写像全射の
    機械検証は validate-knowledge-graph.py --profile doctrine の責務)。
    """
    registry = _doctrine_registry()
    concern_ids = (registry.get("category_concern_map") or {}).get(cat_id) or []
    concerns = {
        c.get("concern_id"): c
        for c in registry.get("concerns", []) or []
        if isinstance(c, dict)
    }
    lines = ["## 上流指針 (doctrine anchor)", ""]
    exception_note = None
    if not concern_ids:
        pending = next(
            (
                p
                for p in registry.get("pending_exceptions", []) or []
                if isinstance(p, dict) and p.get("category") == cat_id
            ),
            None,
        )
        if pending and pending.get("approval_state") == "approved" and pending.get("concerns"):
            concern_ids = pending["concerns"]
            exception_note = (
                "- 本カテゴリは共通シード (categories) 外のプロジェクト固有カテゴリで、"
                f"approved な pending 例外 (owner: {pending.get('owner', '-')}) として上流指針を確定している。"
            )
    if not concern_ids:
        lines.append(
            "- (doctrine-anchor-registry の category_concern_map に未帰属。"
            "pending 例外の owner/reason/approval_state を registry 側で解決すること)"
        )
        return "\n".join(lines)
    if exception_note:
        lines += [exception_note, ""]
    lines += ["| concern | authority (正本) | 導く上流原則 | 出典 |", "|---|---|---|---|"]
    for cid in concern_ids:
        c = concerns.get(cid) or {}
        lines.append(
            f"| {cid} | {c.get('authority', '-')} | {c.get('guides', '-')} | "
            f"{c.get('source_ref', '-')} |"
        )
    lines += [
        "",
        "- 本章の確定内容 (質疑録) は上記 authority を上流指針として適用する。"
        "具体技術の選定はこの指針に従属し、指針との乖離は再オープン (R4-reopen) の根拠になる。",
    ]
    return "\n".join(lines)


_DEEP_CARD_SECTIONS = (
    ("目的", "目的"),
    ("解決する問題", "解決する問題"),
    ("適用条件", "適用条件"),
    ("非適用条件", "非適用条件"),
    ("トレードオフ・失敗モード", "トレードオフ・失敗モード"),
    ("目的達成への寄与", "goalへの寄与"),
)


def _markdown_sections(text: str) -> dict[str, str]:
    matches = list(re.finditer(r"^##\s+(.+?)\s*$", text, re.M))
    sections: dict[str, str] = {}
    for index, match in enumerate(matches):
        end = matches[index + 1].start() if index + 1 < len(matches) else len(text)
        sections[match.group(1).strip()] = text[match.end() : end].strip()
    return sections


def _card_title(text: str, fallback: str) -> str:
    match = re.search(r"^#\s+(.+?)\s*$", text, re.M)
    return match.group(1).strip() if match else fallback


def _render_markdown_card(filename: str) -> list[str]:
    """C04 deep cardの目的適合情報を参照先から章本文へ実体化する。"""
    path = _DESIGN_KNOWLEDGE_DIR / filename
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as exc:
        raise CompileError(f"設計知識cardを読めない: {filename}: {exc}") from exc
    sections = _markdown_sections(text)
    missing = [heading for heading, _ in _DEEP_CARD_SECTIONS if not sections.get(heading)]
    if missing:
        raise CompileError(f"設計知識card {filename} の深度項目欠落: {missing}")
    lines = [f"### {_card_title(text, filename)}", "", f"- 出典カード: `{DESIGN_REF_BASE}/{filename}`"]
    for heading, label in _DEEP_CARD_SECTIONS:
        lines.extend(["", f"#### {label}", "", sections[heading]])
    return lines


def _candidate_applies_to_chapter(spec: dict, candidate: dict, cat_id: str) -> bool:
    categories = candidate.get("categories")
    if isinstance(categories, list) and categories:
        return cat_id in categories
    candidate_goals = set(candidate.get("serves_goals") or [])
    return bool(candidate_goals.intersection(chapter_serves_goals(spec, cat_id)))


def _render_candidate_card(candidate: dict) -> list[str]:
    card = candidate.get("card") or {}
    title = candidate.get("topic") or candidate.get("id") or "knowledge candidate"
    lines = [
        f"### {title}",
        "",
        f"- project candidate: `{candidate.get('id', '-')}` (`{candidate.get('status', '-')}`)",
        f"- 解決対象: {candidate.get('problem', '-')}",
    ]
    fields = (
        ("purpose", "目的"),
        ("problems", "解決する問題"),
        ("applies_when", "適用条件"),
        ("does_not_apply_when", "非適用条件"),
        ("tradeoffs", "トレードオフ"),
        ("failure_modes", "失敗モード"),
        ("goal_contribution", "goalへの寄与"),
    )
    for key, label in fields:
        value = card.get(key)
        lines.extend(["", f"#### {label}", ""])
        if isinstance(value, list):
            lines.extend(f"- {item}" for item in value)
        else:
            lines.append(str(value or "(未記入)"))
    return lines


def render_design_refs(cat_id: str, spec: dict | None = None) -> str:
    """設計知識をpathだけでなく、目的達成に使える意味項目まで章へ描画する。"""
    refs = category_design_refs(cat_id)
    lines = ["## 適用された設計知識", ""]
    if not refs:
        lines.append(
            f"- `{DESIGN_REF_BASE}/resource-map.yaml` "
            "(このカテゴリ専用の deep card は resource-map に未定義。"
            "本章の設計判断は「上流指針 (doctrine anchor)」節の authority と"
            "「確定内容 (質疑録)」を正本とする)"
        )
    else:
        for index, filename in enumerate(refs):
            if index:
                lines.extend(["", "---", ""])
            lines.extend(_render_markdown_card(filename))

    if spec is not None:
        candidates = [
            candidate
            for candidate in spec.get("knowledge_candidates", []) or []
            if isinstance(candidate, dict)
            and candidate.get("status") in {"deepened", "promoted"}
            and _candidate_applies_to_chapter(spec, candidate, cat_id)
        ]
        for candidate in candidates:
            lines.extend(["", "---", ""])
            lines.extend(_render_candidate_card(candidate))
    return "\n".join(lines)


def render_citations(refs: list[dict], *, empty_note: str) -> str:
    """最新ドキュメント出典表を組み立てる (R2-render の最新ドキュメント出典反映)。"""
    lines = ["## 最新ドキュメント出典", ""]
    if not refs:
        lines.append(empty_note)
        return "\n".join(lines)
    lines.append("| 対象 | バージョン | 公式発行元 | 出典URL | 取得 | 最新確認 |")
    lines.append("|---|---|---|---|---|---|")
    for ref in refs:
        lines.append(
            "| {tid} | {ver} | {pub} ({host}) | {url} | {ret} | {chk} |".format(
                tid=ref.get("target_id", "-"),
                ver=_ref_version(ref),
                pub=ref.get("official_publisher", "-"),
                host=_ref_host(ref),
                url=ref.get("source_url", "-"),
                ret=ref.get("retrieved_at", "-"),
                chk=ref.get("latest_checked_at", "-"),
            )
        )
    return "\n".join(lines)


def render_chapter(spec: dict, cat_id: str, refs_by_cat: dict[str, list[dict]]) -> str:
    """1 カテゴリ章の完全な Markdown を組み立てる (frontmatter + 状態表 + 設計知識 + 出典)。"""
    label = category_label(spec, cat_id)
    agg = category_aggregate(spec, cat_id)
    refs = refs_by_cat.get(cat_id, [])
    parts = [
        render_frontmatter(spec, cat_id),

KNOWLEDGE_CANDIDATE_STATUSES = (
    "discovered",
    "qualified",
    "deepened",
    "promoted",
)
KNOWLEDGE_CARD_REQUIRED_FIELDS = (
    "purpose",
    "background",
    "problems",
    "core_concepts",
    "applies_when",
    "does_not_apply_when",
    "tradeoffs",
    "failure_modes",
    "goal_contribution",
    "primary_sources",
    "freshness",
)
_KNOWLEDGE_ID_RE = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def _require_candidate_value(value, label: str) -> None:
    if isinstance(value, str):
        valid = bool(value.strip())
    elif isinstance(value, (list, dict)):
        valid = bool(value)
    else:
        valid = value is not None
    if not valid:
        raise TransitionError(f"knowledge candidate: {label} が空")


def _validate_candidate_sources(source_refs: object) -> None:
    """qualified 以降の根拠を、公式/一次 HTTPS + 確認時刻に限定する。"""
    if not isinstance(source_refs, list) or not source_refs:
        raise TransitionError("knowledge candidate: qualified 以降は source_refs が非空必須")
    for index, source in enumerate(source_refs):
        if not isinstance(source, dict):
            raise TransitionError(f"knowledge candidate: source_refs[{index}] は object 必須")
        url = source.get("url")
        if not isinstance(url, str) or not url.startswith("https://"):
            raise TransitionError(
                f"knowledge candidate: source_refs[{index}].url は HTTPS 必須"
            )
        if source.get("official_or_primary") is not True:
            raise TransitionError(
                f"knowledge candidate: source_refs[{index}] は official_or_primary=true 必須"
            )
        _require_candidate_value(source.get("checked_at"), f"source_refs[{index}].checked_at")


def _validate_deep_knowledge_card(card: object) -> None:
    """C04 deep-card の意味フィールドを candidate の deepened 以降でも強制する。"""
    if not isinstance(card, dict):
        raise TransitionError("knowledge candidate: deepened 以降は card object 必須")
    for field in KNOWLEDGE_CARD_REQUIRED_FIELDS:
        _require_candidate_value(card.get(field), f"card.{field}")
    primary_sources = card.get("primary_sources")
    if not isinstance(primary_sources, list):
        raise TransitionError("knowledge candidate: card.primary_sources は配列必須")
    for index, source in enumerate(primary_sources):
        if not isinstance(source, dict):
            raise TransitionError(
                f"knowledge candidate: card.primary_sources[{index}] は object 必須"
            )
        locator = source.get("locator")
        if not isinstance(locator, str) or not locator.startswith("https://"):
            raise TransitionError(
                f"knowledge candidate: card.primary_sources[{index}].locator は HTTPS 必須"
            )


def set_knowledge_candidate(state: dict, candidate: dict) -> None:
    """seed 外 candidate を stable id で upsertし、前進方向の状態遷移だけを許可する。"""
    if not isinstance(candidate, dict):
        raise TransitionError("knowledge candidate は object 必須")
    candidate_id = candidate.get("id")
    if not isinstance(candidate_id, str) or not _KNOWLEDGE_ID_RE.fullmatch(candidate_id):
        raise TransitionError("knowledge candidate: id は kebab-case の stable id 必須")
    for field in ("topic", "status", "problem", "serves_goals"):
        _require_candidate_value(candidate.get(field), field)
    status = candidate.get("status")
    if status not in KNOWLEDGE_CANDIDATE_STATUSES:
        raise TransitionError(f"knowledge candidate: status={status!r} が許容値外")
    if not isinstance(candidate.get("source_refs"), list):
        raise TransitionError("knowledge candidate: source_refs は配列必須")

    serves = _normalize_serves(candidate.get("serves_goals"))
    goal_ids = set(
        _foundation_goal_ids((state.get("requirements_foundation") or {}).get("goals", []))
    )
    dangling = [goal_id for goal_id in serves if goal_id not in goal_ids]
    if dangling:
        raise TransitionError(
            f"knowledge candidate: serves_goals {dangling} が実在 goal を指さない"
        )

    status_index = KNOWLEDGE_CANDIDATE_STATUSES.index(status)
    if status_index >= KNOWLEDGE_CANDIDATE_STATUSES.index("qualified"):
        _validate_candidate_sources(candidate.get("source_refs"))
    if status_index >= KNOWLEDGE_CANDIDATE_STATUSES.index("deepened"):
        _validate_deep_knowledge_card(candidate.get("card"))
    if status == "promoted":
        _require_candidate_value(candidate.get("curation_ref"), "curation_ref")

    records = list(state.get("knowledge_candidates") or [])
    existing_index: int | None = None
    for index, current in enumerate(records):
        if isinstance(current, dict) and current.get("id") == candidate_id:
            existing_index = index
            if current.get("topic") != candidate.get("topic"):
                raise TransitionError("knowledge candidate: stable topic は変更できない")
            current_status = current.get("status")
            if current_status not in KNOWLEDGE_CANDIDATE_STATUSES:
                raise TransitionError("knowledge candidate: 既存 status が不正")
            current_index = KNOWLEDGE_CANDIDATE_STATUSES.index(current_status)
            if status_index not in (current_index, current_index + 1):
                raise TransitionError(
                    "knowledge candidate: lifecycle は同一status更新または1段階前進のみ"
                )
            break
    if existing_index is None and status != "discovered":
        raise TransitionError("knowledge candidate: 新規 candidate は discovered から開始する")

    normalized = dict(candidate)
    normalized["serves_goals"] = serves
    if existing_index is None:
        records.append(normalized)
    else:
        records[existing_index] = normalized
